import csv
tid='43017c43-0ad2-5eef-8e41-95a8780d3143'
dates={'2018-10-23':{}, '2018-07-18':{}}
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        if r['timeseries_id']==tid:
            ts=r['timestamp']
            date=ts[:10]
            if date in dates:
                hr=int(ts[11:13])
                dates[date][hr]=float(r['value'])

for d in dates:
    occ=sum(v for h,v in dates[d].items() if 8<=h<=18)
    unocc=sum(v for h,v in dates[d].items() if not (8<=h<=18))
    print(d, "occ", occ, "unocc", unocc, "hours count", len(dates[d]))
